SELECT '97e440b7-bef7-597c-a67c-40dbfa6ef98a'::uuid,'محاضرات متنوعة - عبد الرحمن منصور','محاضرات متنوعة - عبد الرحمن منصور مع عبد الرحمن منصور. دروس صوتية متحقق منها من مصدر إسلام ويب.','عبد الرحمن منصور','الشيخ عبد الرحمن منصور، داعية ومحاضر في التربية الأسرية وبناء البيوت وإصلاح العلاقات، له سلاسل ودروس صوتية متعددة.','b6393bd3-deea-403f-88af-f7ae0b34736c'::uuid,'religious','https://audio.islamweb.net/media/contentver3/img/logo.png','beginner',(SELECT id FROM hosts WHERE slug='abdulrahman-mansour' LIMIT 1),0,0,NOW()
